const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const state = {genre:'narrative', role:'student', report:null, tab:'overview', demo:false, busy:false, revision:0, deduction:0};
const focus = {
 narrative:[['开头与结尾','看铺垫与呼应，让故事自然收束。'],['详略分配','突出关键情节，把笔墨留给重要时刻。'],['心理描写','捕捉内心变化，让情感真实可感。']],
 argumentative:[['论点是否正确','审视立场与题意，判断是否清晰、合理。'],['论证是否充分','以 P.E.E.L 展开例证、分析与扣题。'],['结论与论点是否一致','检查推论，避免前后矛盾或过度概括。']]
};
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function count(s){return (s.match(/[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]|[A-Za-z0-9]+/g)||[]).length;}
function feedback(text){$('#feedback').textContent=text;}
function invalidate(){state.revision++;state.report=null;state.deduction=0;$('#report-section').hidden=true;$('#step-review').classList.remove('current');$('#step-grow').classList.remove('current');}
function updateCount(){$('#word-count').textContent=`${count($('#essay').value)} 字`;}
function selectGenre(genre){if(state.genre!==genre)invalidate();state.genre=genre;$$('[data-genre]').forEach(b=>{const selected=b.dataset.genre===genre;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);});$('#focus-title').textContent=genre==='narrative'?'让故事有画面、有温度':'让观点有依据、有深度';$('#focus-list').innerHTML=focus[genre].map(([title,desc],i)=>`<div class="focus-item"><span class="focus-number">0${i+1}</span><div><h3>${title}</h3><p>${desc}</p></div></div>`).join('');}
function setBusy(busy){state.busy=busy;$$('#review-button, #demo-button, [data-upload], #topic-upload, #clear-button, [data-genre]').forEach(b=>b.disabled=busy);$('#review-button').classList.toggle('loading',busy);$('#review-button').innerHTML=busy?'正在细读与批改，请稍候…':'<span>✧</span> 开始批改 <span>→</span>';}
function switchView(view){$('#workshop-view').hidden=view!=='workshop';$('#rubric-view').hidden=view!=='rubric';$('#lessons-view').hidden=view!=='lessons';$('#breadcrumb').textContent=({rubric:'评分标准',lessons:'图解写作',workshop:'作文工坊'})[view]||'作文工坊';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));window.scrollTo({top:0,behavior:'smooth'});}
async function request(url,options={}){if(window.WenmoPages)return window.WenmoPages.request(url,options);const response=await fetch(url,options);let data;try{data=await response.json();}catch{throw Error('服务器响应异常，请稍后重试。');}if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'请检查题目、作文长度与文件格式后重试。');return data;}
async function upload(file,target){if(!file||state.busy)return;if(file.size>8*1024*1024){feedback('文件不能超过8 MB。');return;}setBusy(true);feedback('正在提取文件文字…');const rev=state.revision;try{const form=new FormData();form.append('file',file);const data=await request('/api/extract',{method:'POST',body:form});if(state.revision!==rev){feedback('输入内容已修改，未覆盖当前文字。请重新上传。');return;}if(target==='topic'&&data.text.length>2000){throw Error('题目文件超过2000字符，请只上传题目或直接输入。');}if($(target==='topic'?'#topic':'#essay').value.trim()&&!window.confirm('上传内容将替换当前文字，是否继续？')){feedback('已保留当前文字。');return;}$(target==='topic'?'#topic':'#essay').value=data.text;invalidate();updateCount();$('#file-status').textContent=target==='essay'?`✓ ${file.name} · 已提取，请校对文字与分段`:'';feedback(target==='topic'?'题目已提取，请核对完整题意。':'作文已提取。请在下方核对文字与分段，并填写题目。');}catch(e){feedback(e.message||'上传失败，请重试。');}finally{setBusy(false);}}
function scorePanel(r){return `<section class="card report-card"><h3>内容 + 表达 = 总分</h3><div class="report-score"><div><strong>${r.scores.content}</strong><small> /30</small><label>内容</label></div><span>+</span><div><strong>${r.scores.expression}</strong><small> /30</small><label>表达</label></div><div class="sum"><strong>${r.total}</strong><small> /60</small><label>扣分前总分</label></div></div><div class="score-bars"><div class="score-bar"><label for="content-meter">内容</label><meter id="content-meter" min="0" max="30" value="${r.scores.content}" aria-label="内容分"></meter><span>${r.scores.content} /30</span></div><div class="score-bar expression"><label for="expression-meter">表达</label><meter id="expression-meter" min="0" max="30" value="${r.scores.expression}" aria-label="表达分"></meter><span>${r.scores.expression} /30</span></div></div><div class="score-reason"><b>内容：</b>${esc(r.scores.content_reason)}</div><div class="score-reason"><b>表达：</b>${esc(r.scores.expression_reason)}</div><div class="deduction-control"><b>${r.word_count} 字</b> · ${esc(r.deduction.note)}<br>${state.role==='teacher'?'<label for="deduction">教师确认字数扣分</label><select id="deduction">'+[0,2,4,6].map(n=>`<option value="${n}" ${state.deduction===n?'selected':''}>${n} 分</option>`).join('')+'</select>':'字数扣分由教师确认。'}<div id="final-score">确认扣分：${state.deduction} 分；复核后总分：${Math.max(0,r.total-state.deduction)} /60</div></div></section>`;}
function issueTable(items,expression=false){return items.length?`<div class="table-wrap"><table><thead><tr><th>原文</th><th>${expression?'优化表达':'问题说明'}</th><th>${expression?'说明':'修改建议'}</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.original)}</td><td>${esc(expression?i.suggestion:i.problem)}</td><td>${esc(expression?i.problem:i.suggestion)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">本次未列出额外问题，请结合教师反馈复核。</p>';}
function render(){const r=state.report;if(!r)return;let html='';if(state.tab==='overview'){html=`<div class="report-grid">${scorePanel(r)}<section class="card report-card"><h3>整体反馈</h3><p>${esc(r.summary)}</p><h3>值得保留的亮点</h3><ul>${r.strengths.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p class="pill">下一步 · ${esc(r.next_step)}</p></section></div><section class="card report-card"><h3>${state.genre==='narrative'?'记叙文':'议论文'} · 三个重点，细读你的文章</h3>${r.analysis.map((a,i)=>`<div class="analysis-block"><h4>0${i+1} / ${esc(a.aspect)}</h4><blockquote>${esc(a.evidence)}</blockquote><p>${esc(a.assessment)}</p><p><b>怎么改：</b>${esc(a.suggestion)}</p></div>`).join('')}</section><section class="card report-card"><h3>具体问题与修改建议</h3>${issueTable(r.issues)}</section><section class="card report-card"><h3>让表达更进一步</h3>${issueTable(r.expressions,true)}</section>`;}else if(state.tab==='corrections'){html=`<section class="card report-card"><h3>逐项检查，保留每一处修改依据</h3><p class="muted">以下为检测到的疑似错别字，不含单纯的风格调整。相同错字多次出现会分别列出；AI可能遗漏或误判，请教师复核。</p>${r.corrections.length?`<div class="table-wrap"><table><thead><tr><th>位置</th><th>原文</th><th>纠正</th><th>原因</th></tr></thead><tbody>${r.corrections.map(c=>`<tr><td>第${c.paragraph}段</td><td class="wrong">${esc(c.original)}</td><td class="right">${esc(c.corrected)}</td><td>${esc(c.explanation)}</td></tr>`).join('')}</tbody></table></div>`:'<p>本次未检测到明确错别字；这不等于保证全文无误，请再读一遍。</p>'}</section>`;}else if(state.tab==='rewrite'){html=`<section class="card report-card"><span class="pill">重点修改 · 第${r.rewrite.paragraph}段</span><h3 style="margin-top:14px">保留你的原意，让表达更进一步</h3><p>${esc(r.rewrite.explanation)}</p><div class="comparison"><section class="card report-card before"><h3>修改前</h3><p class="passage">${esc(r.rewrite.original)}</p></section><section class="card report-card after"><h3>修改后</h3><p class="passage">${esc(r.rewrite.improved)}</p></section></div></section>`;}else{html=`<section class="card report-card"><span class="pill">${state.genre==='narrative'?'记叙文':'议论文'} · 原创教学范文 · ${count(r.model_essay.paragraphs.map(p=>p.text).join('\n'))} 字</span><h3 class="model-title">${esc(r.model_essay.title)}</h3><p class="muted">题目：${esc($('#topic').value)}。阅读时结合旁批观察写法，再尝试用自己的经历与思考完成写作。</p>${r.model_essay.paragraphs.map((p,i)=>`<div class="annotated-row"><p>${esc(p.text)}</p><aside class="margin-note"><b>旁批 / ${String(i+1).padStart(2,'0')}</b>${esc(p.note)}</aside></div>`).join('')}</section>`;}$('#report-content').innerHTML=html;const deduction=$('#deduction');if(deduction)deduction.addEventListener('change',()=>{state.deduction=Number(deduction.value);$('#final-score').textContent=`确认扣分：${state.deduction} 分；复核后总分：${Math.max(0,r.total-state.deduction)} /60`;});}
function showReport(report){state.report=report;state.deduction=0;state.tab='overview';$('#report-section').hidden=false;$('#demo-banner').hidden=!report.demo;$('#report-meta').textContent=`${$('#topic').value} · ${state.genre==='narrative'?'记叙文':'议论文'} · ${report.word_count} 字 · ${report.demo?'预设教学示例':'AI批改，待教师复核'}`;$('#correction-count').textContent=report.corrections.length;$$('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===state.tab));$('#step-review').classList.add('current');$('#step-grow').classList.add('current');render();$('#report-section').scrollIntoView({behavior:'smooth',block:'start'});}
async function runReview(){if(state.busy)return;const topic=$('#topic').value.trim(),essay=$('#essay').value.trim();if(!topic){feedback('请先输入完整的作文题目。');$('#topic').focus();return;}if(essay.length<20){feedback('请输入至少20个字符的作文正文。');$('#essay').focus();return;}setBusy(true);feedback('正在通读全文、评分、纠错，并编写带旁批的范文，通常需要1–2分钟。');const revision=state.revision;try{const data=await request('/api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({genre:state.genre,topic,essay}),signal:AbortSignal.timeout(160000)});if(state.revision!==revision){feedback('批改期间正文或题目已修改，请重新批改以确保报告对应当前版本。');return;}feedback('批改完成。建议结合教师反馈复核评分与修改建议。');showReport(data);}catch(e){feedback(e.name==='TimeoutError'?'批改超时，请稍后重试，当前文字仍保留。':e.message);}finally{setBusy(false);}}
async function loadDemo(){if(state.busy)return;if(($('#essay').value.trim()||$('#topic').value.trim())&&!window.confirm('示例会替换当前题目和作文，是否继续？'))return;setBusy(true);try{const data=await request('/api/demo/'+state.genre);$('#topic').value=data.topic;$('#essay').value=data.essay;invalidate();updateCount();$('#file-status').textContent='当前为预设教学示例';feedback('已载入示例。这份预设报告仅展示批改格式与教学方法。');showReport(data.report);}catch(e){feedback(e.message);}finally{setBusy(false);}}
function exportReport(){const r=state.report;if(!r)return;const lines=['文墨 · H1 华文作文批改报告',r.demo?'【预设教学示例，不是实时批改】':'【AI辅助批改，待教师复核】','题目：'+$('#topic').value,'文体：'+(state.genre==='narrative'?'记叙文':'议论文'),`字数：${r.word_count}`,`内容：${r.scores.content}/30；表达：${r.scores.expression}/30；合计：${r.total}/60`,`教师确认字数扣分：${state.deduction}；复核后：${Math.max(0,r.total-state.deduction)}/60`,r.deduction.note,'内容评分理由：'+r.scores.content_reason,'表达评分理由：'+r.scores.expression_reason,'\n原文', $('#essay').value,'\n整体反馈',r.summary,'\n优点',...r.strengths,'\n文体分析',...r.analysis.map(a=>`${a.aspect}\n引用：${a.evidence}\n分析：${a.assessment}\n建议：${a.suggestion}`),'\n错别字（需复核）',...(r.corrections.length?r.corrections.map(c=>`第${c.paragraph}段：${c.original} → ${c.corrected}；${c.explanation}`):['本次未检测到明确错字，不保证没有遗漏。']),'\n具体问题',...r.issues.map(i=>`${i.original}\n问题：${i.problem}\n建议：${i.suggestion}`),'\n表达优化',...r.expressions.map(i=>`${i.original} → ${i.suggestion}；${i.problem}`),'\n重点段落优化',`第${r.rewrite.paragraph}段`,r.rewrite.explanation,'原段：'+r.rewrite.original,'改写：'+r.rewrite.improved,'\n范文与旁批',r.model_essay.title,...r.model_essay.paragraphs.map((p,i)=>`${p.text}\n【第${i+1}段旁批】${p.note}`),'\n下一步：'+r.next_step];const blob=new Blob(['\ufeff'+lines.join('\n\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='文墨_作文批改报告.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
$$('[data-genre]').forEach(b=>b.addEventListener('click',()=>selectGenre(b.dataset.genre)));
$$('[data-upload]').forEach(b=>b.addEventListener('click',()=>{selectGenre(b.dataset.upload);$('#essay-file').click();}));
$('#essay-file').addEventListener('change',e=>{upload(e.target.files[0],'essay');e.target.value='';});
$('#topic-file').addEventListener('change',e=>{upload(e.target.files[0],'topic');e.target.value='';});
$('#topic-upload').addEventListener('click',()=>$('#topic-file').click());
const drop=$('#drop-zone');['dragenter','dragover'].forEach(event=>drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('dragover');}));['dragleave','drop'].forEach(event=>drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('dragover');}));drop.addEventListener('drop',e=>upload(e.dataTransfer.files[0],'essay'));
['#topic','#essay'].forEach(s=>$(s).addEventListener('input',()=>{invalidate();updateCount();$('#file-status').textContent='';}));
$('#clear-button').addEventListener('click',()=>{if(($('#essay').value||$('#topic').value)&&!window.confirm('清空当前题目、作文和报告？'))return;$('#topic').value='';$('#essay').value='';$('#file-status').textContent='';invalidate();updateCount();feedback('');});
$('#review-button').addEventListener('click',runReview);$('#demo-button').addEventListener('click',loadDemo);$('#rubric-link').addEventListener('click',()=>switchView('rubric'));$('#guide-button').addEventListener('click',()=>$('#guide').showModal());['#close-guide','#guide-done'].forEach(s=>$(s).addEventListener('click',()=>$('#guide').close()));
$('#role-button').addEventListener('click',()=>{state.role=state.role==='student'?'teacher':'student';$('#role-button').textContent=(state.role==='teacher'?'教师':'学生')+'视角 ⇄';$('.avatar').textContent=state.role==='teacher'?'师':'学';render();});
$$('[data-tab]').forEach((b,i)=>{b.id='tab-'+b.dataset.tab;b.setAttribute('aria-controls','report-content');b.addEventListener('click',()=>{state.tab=b.dataset.tab;$$('[data-tab]').forEach(t=>t.setAttribute('aria-selected',t===b));render();});b.addEventListener('keydown',e=>{const tabs=$$('[data-tab]');if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const next=tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next.focus();next.click();}});});$('#report-content').setAttribute('role','tabpanel');$('#export-button').addEventListener('click',exportReport);
selectGenre(state.genre);request('/api/status').then(s=>{$('#connection-status').textContent=s.ai_ready?'● OpenAI 批改服务已配置 · 可提交批改':s.backend_missing?'○ 自动批改服务尚未连接 · 可体验示例':'○ OpenAI 尚未配置 · 可先体验示例';}).catch(()=>{$('#connection-status').textContent='服务连接失败，请刷新页面重试。';});

// Use inline SVG so UI icons do not depend on the machine's symbol fonts.
const uploadIcon = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/></svg>';
$('.upload-icon').innerHTML=uploadIcon;
$('.upload-icon').style.display='grid';
$('.upload-icon').style.placeItems='center';
